package com.veyra.storage;import org.junit.jupiter.api.Test;import java.io.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;class FilesystemStorageProviderTest{@Test void store()throws Exception{var s=new FilesystemStorageProvider(Files.createTempDirectory("v").toString(),1);var f=s.store(new ByteArrayInputStream("abc".getBytes()),"a.pdf","application/pdf",3);assertTrue(s.exists(f.storageKey()));}@Test void rejectsExe()throws Exception{var s=new FilesystemStorageProvider(Files.createTempDirectory("v").toString(),1);assertThrows(IllegalArgumentException.class,()->s.store(new ByteArrayInputStream(new byte[]{1}),"a.exe","x",1));}}